#include <iostream>
#include <memory>

struct Sensor {
    Sensor() { std::cout << "المستشعر بدأ العمل\n"; }
    ~Sensor() { std::cout << "المستشعر توقف وتحررت الذاكرة تلقائياً!\n"; }
    void read() { std::cout << "قراءة البيانات: 24.5C\n"; }
};

int main() {
    // ملكية حصرية آمنة بنسبة 100% ضد تسرب الذاكرة
    auto sensor = std::make_unique<Sensor>();
    sensor->read();

    // نقل الملكية إلى مؤشر آخر
    auto nextOwner = std::move(sensor);
    // sensor الآن فارغ (nullptr)
    return 0; // عند الخروج يتحرر Sensor تلقائياً!
}

#include <iostream>
#include <unordered_map>
#include <string>

int main() {
    std::unordered_map<std::string, int> userAges;
    userAges["Ahmad"] = 28;
    userAges["Sara"] = 24;

    auto it = userAges.find("Ahmad");
    if (it != userAges.end()) {
        std::cout << "عمر أحمد: " << it->second << '\n';
    }
    return 0;
}

